contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint256 beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        assert(!reverted ? (afterPot == beforePot + amount && afterBalance == beforeBalance + amount) || (afterPot == 0 && afterBalance == beforeBalance) : (afterPot == beforePot && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

